    if(part==='users')content=`<input class="input" id="user-search" placeholder="Search name, username or ID" aria-label="Search users"><div class="card" id="admin-user" style="margin-top:15px"><div class="card-top"><div class="avatar peach">AM</div><div class="card-copy"><h3>${esc(state.user.name)}</h3><p>@${esc(state.user.username)} · #${state.user.id}</p></div>${badge('Active','green')}</div><div class="detail-list">${detail('Credits',cr(state.balance.cr)+' CR')}${detail('Available assets',asset(state.balance.asset)+' ASSET')}${detail('Joined',date(state.createdAt))}${detail('Language','English')}</div><button class="soft-button full" data-route="admin/ledger">View account ledger</button></div><p id="user-not-found" class="small muted" hidden style="margin-top:20px">No matching users.</p>`;
    if(part==='ledger')content=`<div class="card"><h3>Balance adjustment</h3><p class="small muted" style="margin:8px 0 17px">Current balance: ${cr(state.balance.cr)} CR</p><form id="admin-adjust-form">${field('Adjustment in CR','amount','',{number:true,placeholder:'Example: 10.00 or -5.00'})}${field('Reason','reason','',{placeholder:'Why is this adjustment needed?',max:160})}${error}<button class="solid-button full" type="submit">Apply adjustment</button></form></div>`+section('Account ledger')+`<div class="card">${state.ledger.map(historyRow).join('')}</div>`;
    if(part==='ads'){const c=state.settings.ads;content=adminForm('ads',field('CR per confirmed view','reward',cr(c.rewardCents),{number:true})+field('Provider daily limit (blank = none)','providerDailyLimit',c.providerDailyLimit??'',{number:true,required:false})+field('Cooldown in seconds','cooldownSeconds',c.cooldownSeconds,{number:true}))+section('Ad sessions')+(Object.values(state.ads.sessions).length?`<div class="card">${Object.values(state.ads.sessions).reverse().map(a=>`<div class="list-row"><div class="card-copy"><div class="list-title">${a.id}</div><div class="list-subtitle">${stamp(a.createdAt)}</div></div>${badge(a.status.replaceAll('_',' '),'gray')}</div>`).join('')}</div>`:empty('play','No sessions yet','Start a demo ad from Ad rewards.'));}
    if(part==='milestones')content=adminForm('milestones',state.settings.milestones.levels.map((l,i)=>`<div class="amount-columns">${field('Views · level '+(i+1),'views'+i,l.views,{number:true})}${field('CR reward','reward'+i,cr(l.rewardCents),{number:true})}</div>`).join(''))+`<div class="notice">${svg('clock')}<span>Bonuses are automatic. Settings apply to the next 50-view series. Progress never resets by date.</span></div>`;
    if(part==='tasks')content=`<button class="solid-button full" data-action="new-task">Create task</button><div style="margin-top:15px">${state.settings.tasks.map(t=>`<div class="card"><div class="card-top">${circle(t.icon)}<div class="card-copy"><h3>${esc(t.title)}</h3><p>+${cr(t.rewardCents)} CR · ${t.category}</p></div></div><p class="small muted" style="margin:12px 0">${esc(t.condition)}</p><button class="${t.active?'outline':'soft'}-button full" data-toggle-task="${esc(t.id)}">${t.active?'Pause task':'Activate task'}</button></div>`).join('')}</div>`;
    if(part==='referrals')content=adminForm('referrals',field('Referral share (%)','percent',state.settings.referrals.percent,{number:true})+`<div class="detail-list">${detail('Eligible source','Confirmed ad rewards')}${detail('Attribution','First valid invitation')}${detail('Reward levels','One')}${detail('Self-referrals','Excluded')}</div>`);
    if(part==='promos')content=`<button class="solid-button full" data-action="new-promo">Create promo code</button><div style="margin-top:15px">${state.promos.map(p=>`<div class="card"><div class="card-top">${circle('ticket')}<div class="card-copy"><h3>${esc(p.code)}</h3><p>+${p.reward} CR · ${p.uses}/${p.maxUses} activations</p></div>${badge(p.active?'Active':'Paused',p.active?'green':'gray')}</div><p class="small muted" style="margin:13px 0">Expires ${date(p.expiresAt)} · Once per user</p><button class="outline-button full" data-toggle-promo="${esc(p.code)}">${p.active?'Pause code':'Activate code'}</button></div>`).join('')}</div>`;
    if(part==='exchange'){const c=state.settings.exchange;content=adminForm('exchange',field('ASSET per 1 CR','rate',String(c.assetMicrosPerCR/1e6),{number:true})+field('Minimum CR','minimum',cr(c.minCRCents).replaceAll(',',''),{number:true})+field('Fee (%)','fee',c.feeBps/100,{number:true}));}
    if(part==='withdrawals'){const c=state.settings.withdrawal;content=adminForm('withdrawal',field('Minimum ASSET','minimum',String(c.minAssetMicros/1e6),{number:true})+field('Fee in ASSET','fee',String(c.feeAssetMicros/1e6),{number:true}))+section('Requests')+(state.withdrawals.length?state.withdrawals.map(w=>`<div class="card"><div class="card-top">${circle('withdraw')}<div class="card-copy"><h3>${asset(w.amount)} ASSET</h3><p>${w.id}</p></div>${badge(w.status.replaceAll('_',' '),'gray')}</div><div class="detail-list">${detail('Address',esc(w.address))}${detail('Fee',asset(w.fee)+' ASSET')}${detail('User receives',asset(w.net)+' ASSET')}</div>${w.status==='under_review'?`<button class="solid-button full" data-review-withdrawal="${w.id}" data-status="approved">Approve request</button>`:''}${w.status==='approved'?`<button class="solid-button full" data-review-withdrawal="${w.id}" data-status="confirmed">Simulate completed payout</button>`:''}${['under_review','approved'].includes(w.status)?`<button class="outline-button full" style="margin-top:8px" data-review-withdrawal="${w.id}" data-status="rejected">Reject and return reserved funds</button>`:''}</div>`).join(''):empty('withdraw','No withdrawal requests','New requests will appear here for review.'));}
    if(part==='audit')content=state.audit.length?`<div class="card">${state.audit.map(a=>`<div class="list-row">${circle('shield','gray')}<div class="card-copy"><div class="list-title">${esc(a.action)}</div><div class="list-subtitle">${esc(a.detail)}<br>${stamp(a.at)} · ${esc(a.actor)}</div></div></div>`).join('')}</div>`:empty('shield','No administrative changes','Changes made here will be recorded with their time and actor.');
